import React, { useState, useEffect } from 'react';
import { Search, Filter, MoreVertical, MessageSquare, X, Phone, Video, Paperclip, Send, Smile, Download, Archive, Trash2, Pin, UserCheck, Bell, Check, CheckCheck, Clock } from 'lucide-react';

const MessagesPage = () => {
  const [selectedMessage, setSelectedMessage] = useState(null);
  const [isMobileChatOpen, setIsMobileChatOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeFilter, setActiveFilter] = useState('all');
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Simuler le chargement initial
    const timer = setTimeout(() => setIsLoading(false), 800);
    return () => clearTimeout(timer);
  }, []);

  const filters = [
    { id: 'all', label: 'Tous', count: 12 },
    { id: 'unread', label: 'Non lus', count: 3 },
    { id: 'archived', label: 'Archivés', count: 2 },
    { id: 'pinned', label: 'Épinglés', count: 1 },
  ];

  const mockMessages = [
    {
      id: 1,
      sender: 'John Doe',
      avatarColor: 'from-blue-500 to-cyan-500',
      initials: 'JD',
      lastMessage: 'Bonjour, j\'ai une question concernant ma commande #ORD-001',
      time: '10:30',
      date: 'Aujourd\'hui',
      unread: true,
      pinned: false,
      online: true,
      messageCount: 3,
      status: 'sent'
    },
    {
      id: 2,
      sender: 'Sarah Smith',
      avatarColor: 'from-purple-500 to-pink-500',
      initials: 'SS',
      lastMessage: 'Merci pour votre aide rapide! La commande est parfaite.',
      time: 'Hier',
      date: 'Hier',
      unread: false,
      pinned: true,
      online: true,
      messageCount: 1,
      status: 'read'
    },
    {
      id: 3,
      sender: 'Mike Johnson',
      avatarColor: 'from-orange-500 to-red-500',
      initials: 'MJ',
      lastMessage: 'Est-ce que le produit sera disponible bientôt?',
      time: '11:45',
      date: '22 Nov',
